<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\{SipTrunks,VoiceCalling,VoiceCallingConfig,QueueChannels};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http};
use Illuminate\Support\Str;
use Tests\TestCase;
class SipProvidersTest extends TestCase {
 use RefreshDatabase;
 private User $admin;
 protected function setUp():void {parent::setUp();\Illuminate\Support\Facades\Cache::flush();Http::preventStrayRequests();Http::fake(['http://10.241.50.10:8088/httpstatus'=>Http::response('OK')]);$this->admin=User::factory()->create(['voice_workspace_id'=>1,'voice_role'=>'admin']);$this->actingAs($this->admin);config(['voice_calling_test'=>['allowed_recipients'=>['+5511999990001'],'daily_limit'=>20,'max_seconds'=>30,'ring_seconds'=>10,'caller_id_confirmed'=>true,'sip_username'=>'ma-calling','sip_password'=>str_repeat('a',64),'event_secret'=>str_repeat('b',64)],'voice_audio_test'=>['enabled'=>true,'sip_username'=>'ma-audio','sip_password'=>'echo-only','event_secret'=>'echo-secret']]);}
 private function data(array $extra=[]):array{return $extra+['id'=>(string)Str::uuid(),'provider'=>'fale_vono','label'=>'Comercial QA','number'=>'+551130009988','host'=>'vono2.me','username'=>'testuser','password'=>'OnlyTest1234','port'=>5060,'transport'=>'udp','dial_format'=>'national','concurrency'=>1,'cps'=>1,'enabled'=>true];}
 private function save(array $d=[]):object{$d=$d?:$this->data();$this->putJson('/api/voice/providers',$d)->assertOk()->assertJsonPath('connection.password_saved',true)->assertJsonMissingPath('connection.password');return DB::table('voice_sip_trunks')->find($d['id']);}
 private function ready(object $row):void {DB::table('voice_sip_trunks')->where('id',$row->id)->update(['registration_state'=>'registered','checked_at'=>now(),'applied_hash'=>app(SipTrunks::class)->hash($row)]);}
 public function test_encrypted_credentials_redacted_read_and_blank_password_preserves_secret():void {$d=$this->data();$row=$this->save($d);$this->assertStringNotContainsString($d['password'],$row->configuration);$response=$this->getJson('/api/voice/providers')->assertOk();$this->assertStringNotContainsString($d['password'],$response->getContent());$this->save(array_replace($d,['password'=>'','label'=>'Novo nome']));$this->assertSame($d['password'],app(SipTrunks::class)->config(DB::table('voice_sip_trunks')->find($row->id))['password']);$this->assertDatabaseCount('voice_outbound_calls',0);Http::assertNothingSent();}
 public function test_rejects_config_injection_and_arbitrary_servers():void {foreach([['id'=>'invalid'],['host'=>'127.0.0.1'],['username'=>"u\ncontext=public"],['password'=>"secret\n[evil]"],['port'=>8080],['transport'=>'tcp'],['concurrency'=>0]] as $bad)$this->putJson('/api/voice/providers',$this->data($bad))->assertUnprocessable();$this->assertDatabaseCount('voice_sip_trunks',0);}
 public function test_only_platform_admin_can_manage_tenant_provider():void {
 config(['discai_bridge_test'=>['required'=>true,'slug'=>'fixture','secret'=>'qa','internal_url'=>'http://portal.test','portal_url'=>'https://app.discai.ia.br']]);
 $this->getJson('/api/voice/providers')->assertUnauthorized();
 $identity=['id'=>10,'version'=>0,'email'=>$this->admin->email,'tenant'=>'fixture'];
 $role='admin';$platform=false;Http::fake(['portal.test/*'=>function()use($identity,&$role,&$platform){return Http::response($identity+['role'=>$role,'platform_admin'=>$platform]);}]);
 $this->withSession(['discai_identity'=>$identity])->getJson('/api/voice/providers')->assertForbidden();
 $this->putJson('/api/voice/providers',$this->data())->assertForbidden();
 $platform=true;
 $this->getJson('/api/voice/providers')->assertOk();
 $role='agent';$platform=false;
 $this->getJson('/api/voice/providers')->assertForbidden();
 }

 public function test_cross_workspace_isolation_and_number_unique():void {$d=$this->data();$row=$this->save($d);$this->putJson('/api/voice/providers',$this->data())->assertConflict();DB::table('voice_workspaces')->insert(['id'=>2,'name'=>'Outra']);$this->admin->forceFill(['voice_workspace_id'=>2])->save();$this->getJson('/api/voice/providers')->assertOk()->assertJsonCount(0,'sip');$this->putJson('/api/voice/providers',$d)->assertForbidden();$this->assertSame([],app(QueueChannels::class)->catalog(2)['voice_numbers']);}
 public function test_registration_freshness_and_configuration_hash_fail_closed():void {$row=$this->save();$s=app(SipTrunks::class);$this->assertFalse($s->ready($row));$this->ready($row);$this->assertTrue($s->connection($row->number)['runtime_ready']);$this->travel(151)->seconds();$this->assertFalse($s->connection($row->number)['runtime_ready']);$this->travelBack();$this->ready($row);config(['voice_calling_test.max_seconds'=>60]);$this->assertFalse($s->connection($row->number)['runtime_ready']);}
 public function test_sip_lifecycle_selects_number_and_never_exposes_carrier_password():void {$row=$this->save();$this->ready($row);$contact=DB::table('voice_contacts')->insertGetId(['workspace_id'=>1,'name'=>'QA','phone'=>'+5511999990001','original_phone'=>'+5511999990001','source'=>'QA','consent'=>true,'consent_evidence'=>'QA']);config(['voice_calling_trunk_test'=>['account_sid'=>'AC'.str_repeat('1',32),'caller_id'=>'+551130000001'],'voice_calling_installed_test'=>true]);$queue=DB::table('voice_live_queues')->insertGetId(['workspace_id'=>1,'name'=>'Saída Vono','direction'=>'outbound','manual_enabled'=>true,'calling_method'=>'sip_trunk','channels_configured'=>true,'voice_number'=>$row->number,'agent_ids'=>json_encode([$this->admin->id])]);$reservation=app(\App\Services\ManualDial::class)->reserve(1,$this->admin->id,['number'=>'+5511999990001','queue_id'=>$queue,'idempotency_key'=>(string)Str::uuid(),'session_id'=>(string)Str::uuid()])['reservation'];$this->getJson('/api/voice/calling?reservation_id='.$reservation->id)->assertOk()->assertJsonPath('methods.sip_trunk.caller_id',$row->number);$d=['contact_id'=>$contact,'queue_reservation_id'=>$reservation->id,'idempotency_key'=>(string)Str::uuid(),'consent_confirmed'=>true,'consent_evidence'=>'Teste isolado autorizado'];$grant=$this->postJson('/api/voice/calling/calls',$d)->assertOk()->json();$this->assertStringNotContainsString('OnlyTest1234',json_encode($grant));$this->assertStringStartsWith('discai-browser-',$grant['username']);$call=DB::table('voice_outbound_calls')->find($grant['id']);$this->assertSame($row->number,$call->caller_id);$this->assertLessThanOrEqual(34,strlen($call->provider_account));preg_match('~sip:([a-f0-9]{64})@~',$grant['destination'],$m);$svc=app(VoiceCalling::class);$start=$svc->event(['token'=>$m[1],'event'=>'start','channel_id'=>'qa.1']);$this->assertTrue($start['allowed']);$this->assertSame('11999990001',$start['dial_number']);$this->assertSame(app(SipTrunks::class)->endpoint($row),$start['endpoint']);$this->putJson('/api/voice/providers',$this->data(['id'=>$row->id]))->assertConflict();$svc->event(['token'=>$m[1],'event'=>'finish','channel_id'=>'qa.1','dial_status'=>'BUSY','cause'=>'17','bill_seconds'=>0]);$this->assertDatabaseHas('voice_outbound_calls',['id'=>$call->id,'status'=>'busy']);Http::assertNotSent(fn($r)=>$r->method()==='POST');}
 public function test_capacity_limit_blocks_second_reserved_channel():void {$row=$this->save();$c=app(SipTrunks::class)->connection($row->number);$contact=DB::table('voice_contacts')->insertGetId(['workspace_id'=>1,'name'=>'QA','phone'=>'+5511999990001','original_phone'=>'+5511999990001','source'=>'QA']);$id=(string)Str::uuid();DB::table('voice_outbound_calls')->insert(['id'=>$id,'workspace_id'=>1,'user_id'=>$this->admin->id,'contact_id'=>$contact,'idempotency_key'=>(string)Str::uuid(),'request_hash'=>str_repeat('a',64),'grant_hash'=>str_repeat('b',64),'configuration_hash'=>str_repeat('c',64),'destination'=>'+5511999990001','caller_id'=>$row->number,'method'=>'sip_trunk','provider_account'=>$c['account_sid'],'status'=>'pending','max_seconds'=>30,'ring_seconds'=>10,'consent_evidence'=>'QA','grant_expires_at'=>now()->addMinute(),'deadline_at'=>now()->addMinutes(2)]);app(SipTrunks::class)->assertCapacity($c,$id);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpException::class);app(SipTrunks::class)->assertCapacity($c);}
 public function test_pjsip_render_has_restricted_context_and_expected_auth():void {$row=$this->save();$s=app(SipTrunks::class);$render=$s->render($row);$this->assertStringContainsString('context=discai-sip-denied',$render);$this->assertStringContainsString('server_uri=sip:vono2.me:5060',$render);$this->assertStringContainsString('send_pai=yes',$render);$this->assertStringContainsString('allow_transfer=no',$render);$this->assertDatabaseCount('voice_outbound_calls',0);}
}
